            flex-direction: column;
            align-items: center;
            justify-content: center;
            box-shadow: 0 4px 15px rgba(0,0,0,0.3);
            z-index: 1000;
            cursor: pointer;
            transition: transform 0.2s, box-shadow 0.2s;
            animation: float 3s ease-in-out infinite;
        }

        @keyframes float {
            0% { transform: translateY(0px); }
            50% { transform: translateY(-10px); }
            100% { transform: translateY(0px); }
        }

        .cart-icon svg { width: 32px; height: 32px; }
        .cart-count {
            font-weight: 700;
            font-size: 1.1rem;
            margin-top: 4px;
        }

        .cart-icon.open {
            background: #ffffff;
            color: #1e1e2e;
            box-shadow: 0 8px 25px rgba(255,107,53,0.4);
        }

        /* Carrinho detalhado */
        .cart-panel {
            position: fixed;
            bottom: 24px;
            right: 24px;
            width: 340px;
            max-height: 420px;
            background: #fff;
            border-radius: 15px;
            box-shadow: 0 8px 30px rgba(0,0,0,0.25);
            z-index: 1001;
            display: none;
            flex-direction: column;
            overflow-y: auto;
            transform: translateY(20px);
            transition: transform 0.3s;
        }

        .cart-panel.open {
            display: flex;
            transform: translateY(0);
        }

        .cart-header {
            background: #1e1e2e;
            color: #fff;
            padding: 16px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .cart-header h2 { font-size: 1.1rem; }
        .close-cart {
            background: none;
            border: none;
            color: #fff;
            font-size: 1.2rem;
            cursor: pointer;
            line-height: 1;
        }

        .cart-item {
            padding: 12px 16px;
            border-bottom: 1px solid #eee;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .cart-item-left { flex: 1; }
        .cart-item-name { font-weight: 600; font-size: 0.95rem; }
        .cart-item-desc { font-size: 0.8rem; color: #777; margin-top: 2px; }
        .cart-item-price { font-weight: 700; color: #1e1e2e; font-size: 0.95rem; }

        .btn-remove {
            background: #ef5350;
            color: #fff;
            border: none;
            padding: 5px 10px;
            border-radius: 6px;
            cursor: pointer;
            font-size: 0.8rem;
            margin-top: 6px;
        }

        .btn-remove:hover { background: #c62828; }

        .cart-total {
            padding: 16px;
            background: #f0f0f5;
            border-top: 2px solid #ff6b35;
        }

        .total-row {
            display: flex;
            justify-content: space-between;
            font-weight: 700;
            font-size: 1.1rem;
            margin-bottom: 14px;
        }

        .btn-order {
            width: 100%;
            background: #1e1e2e;
            color: #fff;
            border: none;
            padding: 14px;
            border-radius: 10px;
            font-size: 1rem;
            cursor: pointer;
            transition: background 0.2s;
        }

        .btn-order:hover { background: #2d2d44; }

        footer {
            margin-top: 30px;
            text-align: center;
            color: #777;
            padding: 20px;
            font-size: 0.85rem;
        }

        /* Toast de confirmação */
        .toast {
            position: fixed;
            top: 20px;
            left: 50%;
            transform: translateX(-50%) translateY(-80px);
            background: #2e7d32;
            color: #fff;
            padding: 12px 24px;
            border-radius: 8px;
            font-weight: 600;
            z-index: 9999;
            transition: transform 0.3s;
            opacity: 0;
        }

        .toast.show {
            transform: translateX(-50%) translateY(0);
            opacity: 1;
        }

        @media (max-width: 768px) {
            body { flex-direction: column; }
            .menu { width: 100%; max-height: 60vh; border-bottom: 1px solid #ddd; }
            .cart-icon { width: 50px; height: 50px; bottom: 10px; right: 10px; }
            .cart-panel { width: 100%; max-height: 90vh; }
