            </div>

            <div class="produto" onclick="addProduct('Cheeseburger Duplo', 'Dois hambúrgueres, cheddar cremoso e bacon.', 42.50)">
                <div class="produto-info">
                    <div class="produto-name">Cheeseburger Duplo</div>
                    <div class="produto-desc">Dois hambúrgueres, cheddar cremoso e bacon.</div>
                </div>
                <span class="produto-price">R$ 42,50</span>
                <button class="btn-add">➕ Adicionar</button>
