        </svg>
        <span class="cart-count" id="cartCount">0</span>
    </div>

    <!-- Painel do carrinho -->
    <div class="cart-panel" id="cartPanel">
        <div class="cart-header">
            <h2>🛒 Sacola</h2>
            <button class="close-cart" onclick="closeCart()">✕</button>
        </div>
        <div id="cartItems"></div>
        <div class="cart-total">
            <div class="total-row">
                <span>Total</span>
                <span id="cartTotal">R$ 0,00</span>
            </div>
            <button class="btn-order" onclick="placeOrder()">🚀 Finalizar Pedido</button>
        </div>
    </div>

    <!-- Toast -->
    <div class="toast" id="toast">Item adicionado! 🎉</div>

    <footer>
        © 2025 SaborExpress — Peça agora pelo app ou WhatsApp!
    </footer>

    <script>
        let cart = [];
        const CART_ID = 'cartItems';

        function addProduct(name, desc, price) {
            const item = { id: Date.now(), name, desc, price };
            cart.push(item);
            updateCart();
            showToast(`${name} adicionado! 🍔`);
        }

        function removeFromCart(id) {
            cart = cart.filter(item => item.id !== id);
            updateCart();
        }

        function updateCart() {
            const count = cart.length;
            document.getElementById('cartCount').textContent = count;
            let itemsHTML = '';

            if (count === 0) {
                itemsHTML = `<div style="text-align:center;padding:30px;color:#999;">
                            <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" fill="none" stroke="currentColor" stroke-width="1.5">
                                <path stroke-linecap="round" stroke-linejoin="round" d="M3 6h18M5 6v13c0 5 3.5 9 9 9 5.5 0 9-4 9-9V6M8 6v5"/>
                            </svg>
                            Sua sacola está vazia
                          </div>`;
            } else {
                let total = 0;
                cart.forEach(item => {
                    const qtd = (cart.filter(c => c.id === item.id).length > 0 ? Math.min(cart.filter(c => c.id === item.id).length, 9) : 1);
                    const subtotal = item.price * qtd;
                    total += subtotal;
                    itemsHTML += `
                        <div class="cart-item">
                            <div class="cart-item-left">
                                <div class="cart-item-name">${item.name}</div>
                                <div class="cart-item-desc">${item.desc}</div>
                            </div>
                            <div style="text-align:right;">
                                <div class="cart-item-price">R$ ${formatPrice(item.price * qtd)}</div>
                                <button class="btn-remove" onclick="removeFromCart(${item.id})">Remover</button>
                            </div>
                        </div>`;
                });
                itemsHTML += `<div style="padding:12px 16px;font-weight:700;color:#1e1e2e;">
                            <small>${cart.length} item(s)</small>
                          </div>`;
            }

            document.getElementById(CART_ID).innerHTML = itemsHTML;
            document.getElementById('cartTotal').textContent = formatPrice(total);
        }

        function formatPrice(value) {
            return 'R$ ' + value.toFixed(2).replace('.', ',');
        }

        function toggleCart() {
            const panel = document.getElementById('cartPanel');
            const icon = document.querySelector('.cart-icon');
            panel.classList.toggle('open');
            icon.classList.toggle('open');
        }

        function closeCart() {
            document.getElementById('cartPanel').classList.remove('open');
            document.querySelector('.cart-icon').classList.remove('open');
        }

        // Fecha o painel ao clicar fora dele
        document.addEventListener('click', function(e) {
            if (!e.target.closest('.cart-icon') && !e.target.closest('.cart-panel')) {
                closeCart();
            }
        });

        function placeOrder() {
            if (cart.length === 0) {
                alert('Adicione algum produto na sacola primeiro! 😄');
                return;
            }
            const total = cart.reduce((sum, i) => sum + i.price * (cart.filter(c => c.id === i.id).length || 1), 0);
            const msg = `✅ Pedido realizado!\n\nTotal: ${formatPrice(total)}\nItens: ${cart.map(i => i.name).join(', ')}`;
            alert(msg);
            cart = [];
            updateCart();
            closeCart();
        }

        function showToast(message) {
            const toast = document.getElementById('toast');
            toast.textContent = message;
            toast.classList.add('show');
            setTimeout(() => toast.classList.remove('show'), 2500);
        }
    </script>
</body>
</html>
